Cc: stable@vger.kernel.org
Link: https://lore.kernel.org/all/20251117151314.xwLAZrWY@linutronix.de/
Fixes: a55ebd47f21f ("counter: add IRQ or GPIO based counter")
Signed-off-by: Alexander Sverdlin <alexander.sverdlin@siemens.com>
Reviewed-by: Sebastian Andrzej Siewior <bigeasy@linutronix.de>
Reviewed-by: Oleksij Rempel <o.rempel@pengutronix.de>
Link: https://lore.kernel.org/r/20251118083603.778626-1-alexander.sverdlin@siemens.com
Signed-off-by: William Breathitt Gray <wbg@kernel.org>

Here is the root cause:
The interrupt handler uses spinlock_t, which under CONFIG_PREEMPT_RT becomes a sleeping lock. However, the driver requested the IRQ with IRQF_NO_THREAD, forcing the handler to run in hardirq context where sleeping is not allowed. This triggers a lockdep warning (invalid wait context) when PROVE_RAW_LOCK_NESTING is enabled. Removing IRQF_NO_THREAD allows the handler to be threaded, enabling it to properly use spinlock_t without context mismatch.

Here is the patch:

 static int interrupt_cnt_probe(struct platform_device *pdev)
 {
 	struct device *dev = &pdev->dev;
 	struct counter_device *counter;
 	struct interrupt_cnt_priv *priv;
 	int ret;

 	counter = devm_counter_alloc(dev, sizeof(*priv));
 	if (!counter)
 		return -ENOMEM;
 	priv = counter_priv(counter);

 	priv->irq = platform_get_irq_optional(pdev,  0);
 	if (priv->irq == -ENXIO)
 		priv->irq = 0;
 	else if (priv->irq < 0)
 		return dev_err_probe(dev, priv->irq, "failed to get IRQ\n");

 	priv->gpio = devm_gpiod_get_optional(dev, NULL, GPIOD_IN);
 	if (IS_ERR(priv->gpio))
 		return dev_err_probe(dev, PTR_ERR(priv->gpio), "failed to get GPIO\n");

 	if (!priv->irq && !priv->gpio) {
 		dev_err(dev, "IRQ and GPIO are not found. At least one source should be provided\n");
 		return -ENODEV;
 	}

 	if (!priv->irq) {
 		int irq = gpiod_to_irq(priv->gpio);

 		if (irq < 0)
 			return dev_err_probe(dev, irq, "failed to get IRQ from GPIO\n");

 		priv->irq = irq;
 	}

 	priv->signals.name = devm_kasprintf(dev, GFP_KERNEL, "IRQ %d",
 					    priv->irq);
 	if (!priv->signals.name)
 		return -ENOMEM;

 	counter->signals = &priv->signals;
 	counter->num_signals = 1;

 	priv->synapses.actions_list = interrupt_cnt_synapse_actions;
 	priv->synapses.num_actions = ARRAY_SIZE(interrupt_cnt_synapse_actions);
 	priv->synapses.signal = &priv->signals;

 	priv->cnts.name = "Channel 0 Count";
 	priv->cnts.functions_list = interrupt_cnt_functions;
 	priv->cnts.num_functions = ARRAY_SIZE(interrupt_cnt_functions);
 	priv->cnts.synapses = &priv->synapses;
 	priv->cnts.num_synapses = 1;
 	priv->cnts.ext = interrupt_cnt_ext;
 	priv->cnts.num_ext = ARRAY_SIZE(interrupt_cnt_ext);

 	counter->name = dev_name(dev);
 	counter->parent = dev;
 	counter->ops = &interrupt_cnt_ops;
 	counter->counts = &priv->cnts;
 	counter->num_counts = 1;

 	irq_set_status_flags(priv->irq, IRQ_NOAUTOEN);
 	ret = devm_request_irq(dev, priv->irq, interrupt_cnt_isr,
-			       IRQF_TRIGGER_RISING | IRQF_NO_THREAD,
-			       dev_name(dev), counter);
+			       IRQF_TRIGGER_RISING, dev_name(dev), counter);
 	if (ret)
 		return ret;

 	mutex_init(&priv->lock);

 	ret = devm_counter_add(dev, counter);
 	if (ret < 0)
 		return dev_err_probe(dev, ret, "Failed to add counter\n");

 	return 0;
 }



